import{_ as a,o as e,c as i,a2 as d}from"./chunks/framework.BW2T23B9.js";const u=JSON.parse('{"title":"卡片渲染与网络隔离","description":"","frontmatter":{},"headers":[],"relativePath":"guide/anki-rendering.md","filePath":"guide/anki-rendering.md","lastUpdated":null}'),r={name:"guide/anki-rendering.md"};function l(o,t,n,h,c,s){return e(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="卡片渲染与网络隔离" tabindex="-1">卡片渲染与网络隔离 <a class="header-anchor" href="#卡片渲染与网络隔离" aria-label="Permalink to &quot;卡片渲染与网络隔离&quot;">​</a></h1><p>Anki 卡片可能包含 HTML、CSS、JavaScript、媒体引用和 cloze 模板。Turna 按卡片能力选择渲染路径，并将网络与脚本视为独立权限。</p><h2 id="渲染路径" tabindex="-1">渲染路径 <a class="header-anchor" href="#渲染路径" aria-label="Permalink to &quot;渲染路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>用途</th><th>平台</th></tr></thead><tbody><tr><td>Flutter HTML</td><td>默认卡面</td><td>支持的客户端平台</td></tr><tr><td>WebView</td><td>需要现场 JavaScript、MathJax 或用户强制时</td><td>Android / iOS</td></tr><tr><td>纯文本</td><td>HTML 路径不可用时的最终降级</td><td>全平台</td></tr></tbody></table><p>Web 与桌面不实例化移动 WebView。降级必须保留可读内容和评分入口，不应显示空白卡。</p><h2 id="自动判定" tabindex="-1">自动判定 <a class="header-anchor" href="#自动判定" aria-label="Permalink to &quot;自动判定&quot;">​</a></h2><p><code>AnkiRenderPolicy</code> 根据 notetype 和卡片能力选择 structured、fidelity 或文本降级。选择结果可以持久化到卡片元数据。用户的全局设置和单牌组覆盖可改变策略，但不能扩大平台不存在的能力。</p><h2 id="javascript" tabindex="-1">JavaScript <a class="header-anchor" href="#javascript" aria-label="Permalink to &quot;JavaScript&quot;">​</a></h2><p>JavaScript 默认关闭。以下场景可能需要临时执行：</p><ul><li>notetype 明确声明 <code>allowJs</code>。</li><li>卡片依赖现场解密。</li><li>模板要求浏览器执行才能产生正文。</li></ul><p>执行 JavaScript 不等于开放网络。两项权限分别判定。</p><h2 id="网络策略" tabindex="-1">网络策略 <a class="header-anchor" href="#网络策略" aria-label="Permalink to &quot;网络策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>策略</th><th>行为</th></tr></thead><tbody><tr><td>完全离线</td><td>通过 CSP 阻断 fetch、XHR、WebSocket 和远程资源</td></tr><tr><td>询问</td><td>首次仍阻断；用户明确允许后仅本次放行</td></tr><tr><td>允许</td><td>按用户设置执行；仍受平台与页面导航限制</td></tr></tbody></table><p>默认值为完全离线。页面跳转拦截不能替代网络拦截，因为脚本可以在不跳转页面的情况下请求外部资源。</p><h2 id="预渲染缓存" tabindex="-1">预渲染缓存 <a class="header-anchor" href="#预渲染缓存" aria-label="Permalink to &quot;预渲染缓存&quot;">​</a></h2><p>某些模板需要执行一次混淆脚本才能得到正文。流程如下：</p><ol><li>在 WebView 中执行模板。</li><li>延时读取 <code>document.body.innerHTML</code>。</li><li>移除 <code>&lt;script&gt;</code>。</li><li>将纯 HTML 写入预渲染缓存。</li><li>后续以 <code>allowJs=false</code> 使用缓存。</li></ol><p>清除此缓存不会删除 note、card、媒体或复习状态。下次复习时按需重新生成。</p><h2 id="媒体" tabindex="-1">媒体 <a class="header-anchor" href="#媒体" aria-label="Permalink to &quot;媒体&quot;">​</a></h2><ul><li>缺失图片显示占位，不阻塞评分。</li><li>原音频失败时可以对卡片文本执行系统 TTS。</li><li>可配置去重、未引用媒体过滤和大图片压缩。</li><li>为兼容旧牌组，导入未引用媒体默认开启。</li></ul><h2 id="安全模式" tabindex="-1">安全模式 <a class="header-anchor" href="#安全模式" aria-label="Permalink to &quot;安全模式&quot;">​</a></h2><p>安全模式是运行时覆盖：强制关闭模板脚本和外部网络，但不改写用户保存的设置。退出安全模式后恢复进入前的配置。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/anki-import">导入 Anki 牌组</a></li><li><a href="/docs/guide/settings">设置系统</a></li><li><a href="/docs/guide/data-and-privacy">本地数据与隐私</a></li></ul>',24)])])}const b=a(r,[["render",l]]);export{u as __pageData,b as default};
